 "content": "from collections import Counter


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    occupied = {(r, c) for r in range(h) for c in range(w) if g[r][c] != bg}

    # Find the longest uninterrupted horizontal/vertical non-background pattern.
    seed = []
    for dr, dc in ((0, 1), (1, 0)):
        for r, c in occupied:
            if (r-dr, c-dc) in occupied:
                continue
            run = []
            rr, cc = r, c
            while (rr, cc) in occupied:
                run.append((rr, cc))
                rr += dr
                cc += dc
            if len(run) > len(seed):
                seed = run
    if len(seed) < 2:
        return g

    seed_set = set(seed)
    markers = occupied - seed_set
    anchor = seed[len(seed) // 2]
    pattern = [(r-anchor[0], c-anchor[1], g[r][c]) for r, c in seed]
    for mr, mc in markers:
        for ro, co, color in pattern:
            rr, cc = mr + ro, mc + co
            if 0 <= rr < h and 0 <= cc < w:
                g[rr][cc] = color
    return g


if __name__ == '__main__':
    pass
